"implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])
    node_map = {}
    parent_map = {}
    children_map = {}
    for node in nodes:
        nid = node['id']
        node_map[nid] = node
        parent = node.get('parent')
        if parent is not None:
            parent_map[nid] = parent
            children_map.setdefault(parent, []).append(nid)
        else:
            root_id = nid
    remaining = set(node_map.keys())
    removal_order = []
    # sort nodes by depth descending, then id ascending
    sorted_nodes = sorted(node_map.values(), key=lambda x: (-x['depth'], x['id']))
    for node in sorted_nodes:
        nid = node['id']
        if nid not in remaining:
            continue
        if nid == root_id:
            continue
        if node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        # check if any child is still present
        children = children_map.get(nid, [])
        has_children_remaining = any(c in remaining for c in children)
        if has_children_remaining:
            continue
        # tentatively remove
        remaining.remove(nid)
        # check required symbols
        symbols_present = set()
        for rid in remaining:
            symbols_present.add(node_map[rid]['symbol'])
        if required_symbols.issubset(symbols_present):
            removal_order.append(nid)
        else:
            remaining.add(nid)
    retained = sorted(remaining)
    return {'retained_ids': retained, 'removal_order': removal_order}"
}
